export default function Joachim({
  p,
  detail,
}: PortraitProps) {
  return (
    <>
      <g transform={ART_TRANSFORM}>
        <rect x="0" y="0" width="1086" height="1448" fill={PAPER} pointerEvents="none" />

        <g {...p('background')} stroke="none">
          <rect x="0" y="0" width="1086" height="1448" />
        </g>

        <g {...p('cloud')} stroke="none">
          <path d={CLOUD_MASK} />
        </g>

        <g {...p('halo')} stroke="none">
          <path d={HALO_MASK} />
        </g>

        {/* Scenic details stay behind Joachim. */}
        <g {...p('symbol')} stroke="none">
          <path d={SYMBOL_MASK} />
        </g>

        <g {...p('mantle')} stroke="none">
          <path d={MANTLE_MASK} />
        </g>

        <g {...p('robe')} stroke="none">
          <path d={ROBE_MASK} />
        </g>

        {/* Staff, scrolls, and rope sit above the clothing but below the hands. */}
        <g {...p('accent')} stroke="none">
          <path d={ACCENT_MASK} />
        </g>

        <g {...p('skin')} stroke="none">
          <path d={SKIN_MASK} />
        </g>

        <g {...p('hair')} stroke="none">
          <path d={HAIR_MASK} />
        </g>

        <path
          {...detail}
          {...ink}
          d={JOACHIM_LINE_ART}
          fill={STROKE}
          stroke="none"
          fillRule="evenodd"
          pointerEvents="none"
          shapeRendering="geometricPrecision"
        />
      </g>
    </>
  );
}